from collections.abc import Iterable, Mapping


def summarize_events(events):
    if isinstance(events, (str, bytes)) or not isinstance(events, Iterable):
        raise TypeError("events must be an iterable")
    output = []
    fields = {
        "key_down": {"type", "key"},
        "key_up": {"type", "key"},
        "move": {"type", "x", "y"},
        "button": {"type", "number", "pressed"},
        "quit": {"type"},
    }
    for event in events:
        if not isinstance(event, Mapping):
            raise TypeError("events must be mappings")
        if "type" not in event:
            raise KeyError("type")
        kind = event["type"]
        if not isinstance(kind, str):
            raise TypeError("type must be a string")
        if kind not in fields:
            raise ValueError("unknown event type")
        missing = fields[kind] - set(event)
        if missing:
            raise KeyError(sorted(missing)[0])
        if set(event) != fields[kind]:
            raise ValueError("unexpected event field")
        if kind == "quit":
            continue
        if kind in ("key_down", "key_up"):
            key = event["key"]
            if not isinstance(key, str):
                raise TypeError("key must be a string")
            if not key:
                raise ValueError("key must not be empty")
            output.append(("DOWN " if kind == "key_down" else "UP ") + key)
        elif kind == "move":
            x, y = event["x"], event["y"]
            if isinstance(x, bool) or not isinstance(x, int) or isinstance(y, bool) or not isinstance(y, int):
                raise TypeError("coordinates must be integers")
            output.append(f"MOVE {x},{y}")
        else:
            number, pressed = event["number"], event["pressed"]
            if isinstance(number, bool) or not isinstance(number, int):
                raise TypeError("number must be an integer")
            if number < 0:
                raise ValueError("number must be non-negative")
            if not isinstance(pressed, bool):
                raise TypeError("pressed must be a boolean")
            output.append(f"BUTTON {number} {'DOWN' if pressed else 'UP'}")
    return tuple(output)

